// 先匹配原业务载荷和明确一次意图，再按真实事实前控制链证明当时非玩家，绝不用今日metadata倒填。
#include "political_governance_agency_authored.hpp"
#include "resident/domains/politics/governance_agencies/political_governance_agency_codec.hpp"
#include <set>
namespace hanmo::resident {namespace {
bool matches_offer(const PoliticalGovernanceAgencyOffer& o,const PoliticalGovernanceAgencyIntent& i){return o.policy_id==i.agency_policy_id&&o.issuer_actor_id==i.principal_actor_id&&o.delegate_actor_id==i.delegate_actor_id;}
Outcome<const PoliticalGovernanceAgencyOffer*> first_offer(const CommonStore& common,const PoliticalGovernanceAgencyState& s,const PoliticalGovernanceAgencyIntent& i){const PoliticalGovernanceAgencyOffer* first=nullptr;std::size_t expected=0,found=0;Integer last=0;for(const auto& row:s.offers.rows())if(matches_offer(row.second,i))++expected;for(const auto& head:common.state().facts.rows()){const auto* o=s.offers.find(head.first);if(!o||!matches_offer(*o,i))continue;auto n=political_governance_agency_fact_sequence(common,head.first,"political_governance_agency_offered");if(!n||*n<=last||o->id!=head.first)return {false,nullptr,common_failure("GovernanceAgencyIntentOfferHistoryMismatch",head.first).error};last=*n;++found;if(!first)first=o;}return found==expected?Outcome<const PoliticalGovernanceAgencyOffer*>{true,first,{}}:Outcome<const PoliticalGovernanceAgencyOffer*>{false,nullptr,common_failure("GovernanceAgencyIntentOfferHistoryMismatch",i.id).error};}
Status command_source(const CommonStore& common,const PoliticalGovernanceAgencyState& s,const PoliticalGovernanceAgencyIntent& i,const PoliticalGovernanceAgencyCommand& command){
 auto first=first_offer(common,s,i);if(!first.ok)return {false,{},first.error};
 return std::visit([&](const auto& c)->Status{using T=std::decay_t<decltype(c)>;
  if constexpr(std::is_same_v<T,PoliticalOfferGovernanceAgency>){if(c.policy_id!=i.agency_policy_id||c.authority.actor_id!=i.principal_actor_id||c.delegate_actor_id!=i.delegate_actor_id||first.value)return common_failure("GovernanceAgencyIntentOfferConsumed",i.id);}
  else if constexpr(std::is_same_v<T,PoliticalAnswerGovernanceAgency>){const auto* o=first.value;if(!o||c.offer_fact_id!=o->id||c.accept!=i.delegate_accepts)return common_failure("GovernanceAgencyIntentAnswerMismatch",i.id);}
  else if constexpr(std::is_same_v<T,PoliticalIssueAgencyGovernance>){const auto* o=first.value;const auto* a=s.answers.find(c.acceptance_fact_id);if(!o||!i.delegate_accepts||c.offer_fact_id!=o->id||!a||!a->accept||a->actor_id!=i.delegate_actor_id||a->offer_fact_id!=o->id||c.executor_actor_id!=i.executor_actor_id)return common_failure("GovernanceAgencyIntentIssueMismatch",i.id);for(const auto& row:s.issues.rows())if(row.second.offer_fact_id==o->id&&row.second.executor_actor_id==i.executor_actor_id)return common_failure("GovernanceAgencyIntentIssueConsumed",i.id);}
  else return common_failure("GovernanceAgencyIntentCommandUnsupported",i.id);
  return common_success();
 },command);
}
}
Status validate_political_governance_agency_authored_command(const CommonStore& common,const PoliticalGovernanceAgencyState& s,const PoliticalGovernanceAgencyIntentCatalog& catalog,const PoliticalGovernanceAgencyAuthoredOrigin& origin,const StableId& actor,const PoliticalGovernanceAgencyCommand& command){if(s.version!=2)return common_failure("GovernanceAgencyIntentVersionPairRequired");auto valid=validate_political_governance_agency_authored_origin(catalog,origin,actor,political_governance_agency_command_kind(command));if(!valid.ok)return valid;return command_source(common,s,*catalog.intents.find(origin.intent_id),command);}
// 首个匹配委任是不可重复的自动目标；后来新手工委任不能将已过期的原自动意图复活。
Status validate_political_governance_agency_authored_source(const CommonStore& common,const PoliticalGovernanceAgencyState& s,const PoliticalGovernanceAgencyIntentCatalog& catalog,const PoliticalGovernanceAgencyAuthoredOrigin& origin,const StableId& source,const PoliticalSuccessionPlayerRead& player){
 if(s.version!=2||!player)return common_failure("GovernanceAgencyIntentHistoryRequired",source);const auto* head=common.state().facts.find(source);if(!head||!political_governance_agency_fact_sequence(common,source,head->kind))return common_failure("GovernanceAgencyIntentActualSourceRequired",source);const auto* intent=catalog.intents.find(origin.intent_id);if(!intent)return common_failure("GovernanceAgencyIntentOriginMismatch",source);
 const PoliticalGovernanceAgencyOffer* offer=nullptr;StableId actor,kind;Integer tick=-1;const std::optional<PoliticalSuccessionPlayerReceipt>* receipt=nullptr;
 if(const auto* o=s.offers.find(source)){if(head->kind!="political_governance_agency_offered"||o->id!=source)return common_failure("GovernanceAgencyIntentActualSourceRequired",source);offer=o;actor=o->issuer_actor_id;kind=political_governance_agency_offer_command;tick=o->tick;receipt=&o->player_receipt;}
 else if(const auto* a=s.answers.find(source)){if(a->id!=source||a->accept!=(head->kind=="political_governance_agency_accepted")||(head->kind!="political_governance_agency_accepted"&&head->kind!="political_governance_agency_declined")||a->accept!=intent->delegate_accepts)return common_failure("GovernanceAgencyIntentAnswerMismatch",source);offer=s.offers.find(a->offer_fact_id);actor=a->actor_id;kind=political_governance_agency_answer_command;tick=a->tick;receipt=&a->player_receipt;}
 else if(const auto* a=s.issues.find(source)){if(a->id!=source||head->kind!="political_governance_agency_issued"||!intent->delegate_accepts||a->executor_actor_id!=intent->executor_actor_id)return common_failure("GovernanceAgencyIntentIssueMismatch",source);offer=s.offers.find(a->offer_fact_id);const auto* accepted=s.answers.find(a->acceptance_fact_id);if(!accepted||!accepted->accept||accepted->actor_id!=intent->delegate_actor_id||accepted->offer_fact_id!=a->offer_fact_id)return common_failure("GovernanceAgencyIntentIssueMismatch",source);bool first=false;for(const auto& h:common.state().facts.rows()){const auto* old=s.issues.find(h.first);if(!old||old->offer_fact_id!=a->offer_fact_id||old->executor_actor_id!=intent->executor_actor_id)continue;if(h.first!=source)return common_failure("GovernanceAgencyIntentIssueConsumed",source);first=true;break;}if(!first)return common_failure("GovernanceAgencyIntentIssueConsumed",source);actor=a->delegate_actor_id;kind=political_governance_agency_issue_command;tick=a->tick;receipt=&a->player_receipt;}
 else return common_failure("GovernanceAgencyIntentActualSourceRequired",source);
 auto first=first_offer(common,s,*intent);if(!first.ok)return {false,{},first.error};
 if(!offer||!matches_offer(*offer,*intent)||first.value!=offer||tick<0||tick>common.tick()||!receipt||receipt->has_value())return common_failure("GovernanceAgencyIntentOriginSourceMismatch",source);
 auto valid=validate_political_governance_agency_authored_origin(catalog,origin,actor,kind);if(!valid.ok)return valid;auto controller=player(tick,source);if(!controller.ok)return {false,{},controller.error};if(controller.value.empty()||!common.actor(controller.value)||controller.value==actor||!common.actor(actor))return common_failure("GovernanceAgencyIntentHistoricalNonPlayerRequired",source);return common_success();
}
}
